"""Source-bound rider position and adjacent-path condition measurement.

The output separates observed travel from the legal judgment that a path is
usable. Synthetic tests prove only the software measurement contract.
"""

from __future__ import annotations

import hashlib
import json
import math
from pathlib import Path


ASSIGNMENT = "testing__C233829__LVMC-11-40-120__cycle_or_scooter_operator"
DEVICES = {"bicycle", "electric_bicycle", "electric_scooter"}


def measure(path: str | Path) -> dict:
    path = Path(path)
    raw = path.read_bytes()
    packet = json.loads(raw)
    return measure_packet(packet, {"path": str(path), "sha256": hashlib.sha256(raw).hexdigest()})


def measure_packet(packet: dict, source: dict) -> dict:
    """Measure an already authenticated saved packet without a second copy."""
    if packet.get("assignment_id") != ASSIGNMENT or not packet.get("original_trace_id"):
        raise ValueError("original assignment and trace identity required")
    if packet.get("ego_device_type") not in DEVICES or not packet.get("ego_actor_id"):
        raise ValueError("covered rider/device identity required")
    if not packet.get("roadway_id") or not packet.get("path_id") or not packet.get("path_designation_source"):
        raise ValueError("roadway, adjacent path and designation source required")
    if packet.get("path_adjacent_to_roadway") is not True:
        raise ValueError("source path adjacency required")
    if packet.get("sidewalk_status") not in ("absent", "present", "unresolved"):
        raise ValueError("source sidewalk status required")
    if packet.get("path_usability_status") not in ("usable", "unusable", "unresolved"):
        raise ValueError("separately reviewed path usability required")
    if not packet.get("path_condition_source") or not packet.get("access_restrictions_source"):
        raise ValueError("path condition and access restriction sources required")
    frames = packet.get("frames")
    if not isinstance(frames, list) or len(frames) < 3:
        raise ValueError("three original frames required")
    observations = []
    previous = None
    for i, frame in enumerate(frames):
        t = frame.get("time_s")
        if isinstance(t, bool) or not isinstance(t, (int, float)) or not math.isfinite(t):
            raise ValueError("finite original frame time required")
        if previous is not None and not 0 < t - previous <= 0.075:
            raise ValueError("ordered 20 Hz frames required")
        previous = t
        for key in ("ego_body_on_roadway", "ego_body_on_designated_path"):
            if not isinstance(frame.get(key), bool):
                raise ValueError(f"original {key} readback required")
        observations.append({"frame_index": i, "time_s": t,
                             "on_roadway": frame["ego_body_on_roadway"],
                             "on_designated_path": frame["ego_body_on_designated_path"]})
    return {"assignment_id": ASSIGNMENT, "original_trace_id": packet["original_trace_id"],
            "source": source,
            "ego_actor_id": packet["ego_actor_id"], "ego_device_type": packet["ego_device_type"],
            "roadway_id": packet["roadway_id"], "path_id": packet["path_id"],
            "path_designation_source": packet["path_designation_source"],
            "path_condition_source": packet["path_condition_source"],
            "access_restrictions_source": packet["access_restrictions_source"],
            "sidewalk_status": packet["sidewalk_status"],
            "path_usability_status": packet["path_usability_status"],
            "observations": observations,
            "roadway_use_observed": any(o["on_roadway"] for o in observations),
            "path_use_observed": any(o["on_designated_path"] for o in observations),
            "review_limit": "Observed position does not decide path usability, access permission, jurisdiction or legal compliance."}

"""Construct named rider routes inside source-designated path or roadway bounds."""

from __future__ import annotations

import hashlib
import json
import math
from pathlib import Path

from path_observation import ASSIGNMENT


def _point(raw):
    if not isinstance(raw, list) or len(raw) != 2:
        raise ValueError("two-dimensional point required")
    if any(isinstance(x, bool) or not isinstance(x, (int, float)) or not math.isfinite(x) for x in raw):
        raise ValueError("finite point required")
    return tuple(float(x) for x in raw)


def _polygon(raw):
    if not isinstance(raw, list) or len(raw) < 3:
        raise ValueError("polygon required")
    points = [_point(p) for p in raw]
    area2 = sum(points[i][0] * points[(i + 1) % len(points)][1] - points[(i + 1) % len(points)][0] * points[i][1] for i in range(len(points)))
    if abs(area2) < 1e-8:
        raise ValueError("nondegenerate polygon required")
    return points


def _inside(point, polygon):
    x, y = point
    inside = False
    for i, a in enumerate(polygon):
        b = polygon[(i + 1) % len(polygon)]
        cross = (b[0] - a[0]) * (y - a[1]) - (b[1] - a[1]) * (x - a[0])
        if abs(cross) < 1e-9 and min(a[0], b[0]) - 1e-9 <= x <= max(a[0], b[0]) + 1e-9 and min(a[1], b[1]) - 1e-9 <= y <= max(a[1], b[1]) + 1e-9:
            return True
        if (a[1] > y) != (b[1] > y):
            if x < a[0] + (y - a[1]) * (b[0] - a[0]) / (b[1] - a[1]):
                inside = not inside
    return inside


def select_route(site_path: str | Path, candidate_id: str, target: str) -> dict:
    """Require a route's waypoints and segment interiors in its named facility."""
    path = Path(site_path)
    raw = path.read_bytes()
    site = json.loads(raw)
    if site.get("assignment_id") != ASSIGNMENT or not site.get("map_id"):
        raise ValueError("source assignment and map identity required")
    if not site.get("roadway_id") or not site.get("path_id") or not site.get("path_designation_source"):
        raise ValueError("source roadway and designated path identities required")
    if site.get("path_adjacent_to_roadway") is not True or site.get("sidewalk_status") != "absent":
        raise ValueError("adjacent path and absent sidewalk required for assigned cell")
    if site.get("path_usability_status") not in ("usable", "unusable", "unresolved"):
        raise ValueError("path usability context required")
    if target not in ("path", "roadway"):
        raise ValueError("target facility must be path or roadway")
    polygon = _polygon(site.get(target + "_polygon"))
    candidates = site.get("route_candidates")
    if not isinstance(candidates, dict) or candidate_id not in candidates:
        raise ValueError("named route candidate required")
    raw_route = candidates[candidate_id]
    if not isinstance(raw_route, list) or len(raw_route) < 2:
        raise ValueError("two or more route waypoints required")
    route = [_point(p) for p in raw_route]
    for a, b in zip(route, route[1:]):
        if a == b:
            raise ValueError("zero-length route segment")
        distance = math.dist(a, b)
        count = max(1, math.ceil(distance / 0.25))
        for i in range(count + 1):
            t = i / count
            point = (a[0] + t * (b[0] - a[0]), a[1] + t * (b[1] - a[1]))
            if not _inside(point, polygon):
                raise ValueError("route leaves target facility polygon")
    return {"assignment_id": ASSIGNMENT, "map_id": site["map_id"],
            "source": {"path": str(path), "sha256": hashlib.sha256(raw).hexdigest()},
            "candidate_id": candidate_id, "target_facility": target,
            "roadway_id": site["roadway_id"], "path_id": site["path_id"],
            "path_designation_source": site["path_designation_source"],
            "path_usability_status": site["path_usability_status"],
            "route_waypoints": raw_route,
            "limit": "Engineering centerline selection only; original rider body position and path usability need independent source readback."}
